\begin{exercise}
\textbf{Counting electrons.} $1.88\times10^{18}$ electrons flow through a resistor each second. Find the current. (Electron charge magnitude $e=1.60\times10^{-19}$ C.)

\textbf{Solution.} Total charge per second is the number of electrons times the charge on each:
\[
\boxed{I=\frac{ne}{t}} \qquad I=\frac{(1.88\times10^{18})(1.60\times10^{-19})}{1}=\boxed{0.301\text{ A}}.
\]
Here $n$ is a pure count of electrons, so $Q=ne$ before dividing by time. Watch the powers of ten: $10^{18}\times10^{-19}=10^{-1}$.
\end{exercise}

\end{exercise}

\begin{exercise}
\textbf{Reading a $V$--$I$ graph.} A resistance wire gives the straight line below through the origin. Find its resistance, and state how the line changes for a shorter wire of the same material and radius.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm,>=stealth]
  \draw[->] (0,0) -- (4,0) node[right] {$I$/A};
  \draw[->] (0,0) -- (0,3.4) node[above] {$V$/V};
  \draw[very thick,blue!70!black] (0,0) -- (3.2,3.2);
  \draw[dashed] (2,0) node[below] {\footnotesize $2.0$} -- (2,2) -- (0,2) node[left] {\footnotesize $4.0$};
  \draw[very thick,red!70!black,dotted] (0,0) -- (3.4,1.7);
  \node[red!70!black] at (3.2,1.15) {\footnotesize shorter};
\end{tikzpicture}
\end{center}

\textbf{Solution.} The line is straight through the origin, so the slope is the resistance. Reading a convenient point, $V=4.0$ V at $I=2.0$ A:
\[
R=\frac{V}{I}=\frac{4.0}{2.0}=\boxed{2.0\ \Omega}.
\]
A shorter wire has smaller $R=\rho\ell/A$, so the slope is smaller (the dotted line). Because $V=IR$, the graph still passes through the origin.
\end{exercise}

\begin{exercise}
\textbf{Resistance that changes with temperature.} A metal wire is connected to a fixed $5.0$ V supply. Its resistance is $5\,\Omega$ at $25^\circ$C and rises to $12\,\Omega$ at $200^\circ$C. The ammeter reads $1.0$ A at $25^\circ$C. Find the reading at $200^\circ$C.

\textbf{Solution.} The supply voltage across the wire stays $V=IR=(1.0)(5)=5.0$ V. At the higher temperature the resistance is larger, so
\[
I=\frac{V}{R}=\frac{5.0}{12}=\boxed{0.42\text{ A}}.
\]
Hotter metal means more resistance and, at fixed voltage, less current. This is why a filament lamp is \emph{not} ohmic.
\end{exercise}

