    \draw[thick] (-2.0, 0.8) rectangle (-1.3, 1.2);
    \node[left, font=\footnotesize] at (-2.1, 1.0) {battery};
    \node[left, font=\tiny] at (-2.1, 1.2) {$+$};
    \node[left, font=\tiny] at (-2.1, 0.8) {$-$};

    % ---- Incoming current arrow ----
    \draw[thick, ->] (-2.8, 2) -- (-2.1, 2) node[midway, above, font=\footnotesize] {$I_{\text{total}}$};

    % ---- Annotations: current values ----
    \node[anchor=south, font=\footnotesize\bfseries, blue!70!black] at (2.7, 2.9) {$I_1 = I_{\text{total}}/2$};
    \node[anchor=north, font=\footnotesize\bfseries, blue!70!black] at (2.7, -0.3) {$I_2 = I_{\text{total}}/2$};

    % ---- Junction connection (bottom) ----
    \draw[thick] (0, 2) -- (0, 0);
    \draw[thick] (4.5, 2) -- (4.5, 0);
  \end{tikzpicture}
\end{center}

\begin{itemize}
  \item Each branch receives part of the total current: $I_1 + I_2 = I_{\text{total}}$.
  \item If both lamps are identical (equal resistance), the current splits equally: $I_1 = I_2 = I_{\text{total}}/2$.
  \item The current through each lamp is \emph{less} than the total current.
  \item In the water analogy: one pipe splits into two smaller pipes; the total water flow rate is conserved, but each branch carries a fraction.
\end{itemize}

\section{Potential, Potential Difference and EMF}

Potential is energy per unit positive charge at one point. Potential difference is the energy transferred per unit charge between two points:
\[
\boxed{V=\frac{W}{Q}} \qquad 1\text{ V}=1\text{ J C}^{-1}.
\]

\begin{exercise}
\textbf{Question.} A cell supplies 12 J when 6 C passes through it. Find its emf. If a 1.0 V resistor carries 0.50 C, how much energy is converted in the resistor?

\textbf{Solution.}
\[
\mathcal E=\frac{W_{\rm supplied}}{Q}=\frac{12}{6}=\boxed{2.0\text{ V}},
\qquad
W_{\rm converted}=VQ=(1.0)(0.50)=\boxed{0.50\text{ J}}.
\]
A source gives energy to charge; a resistor converts electrical energy to other forms.
\end{exercise}

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[->] (0,0) -- (8.5,0) node[right] {position around circuit};
  \draw[->] (0,0) -- (0,4.4) node[above] {potential};
  \draw[very thick] (0.7,0.7) -- (1.7,0.7);
  \draw[very thick,->] (1.7,0.7) -- (1.7,3.7) node[midway,right] {cell: rise $\mathcal E$};
  \draw[very thick] (1.7,3.7) -- (4.5,3.7);
  \draw[very thick,->] (4.5,3.7) -- (4.5,2.2) node[midway,right] {$V_1$};
  \draw[very thick] (4.5,2.2) -- (6.5,2.2);
  \draw[very thick,->] (6.5,2.2) -- (6.5,0.7) node[midway,right] {$V_2$};
  \draw[very thick] (6.5,0.7) -- (8,0.7);
\end{tikzpicture}
\end{center}

For a complete loop with an ideal cell,
\[
\boxed{\text{total emf}=\text{sum of potential drops}}.
\]
A component causes no potential change if it is bypassed by an ideal wire.

\needspace{8\baselineskip}
\begin{exercise}[nobreak=true]
\textbf{Question.} A 6 V supply is connected across three identical $2\,\Omega$ resistors in series. Point B, at the negative terminal, is earthed. Find the potentials after the first and second resistors when moving from the positive terminal.

