  \draw[thick] (4.0,1.7) -- (4.6,1.7);
  \draw[thick] (4.6,1.4) rectangle (6.0,2.0) node[pos=.5] {$2\,\Omega$};
  \draw[thick] (6.0,1.7) -- (6.6,1.7) -- (6.6,0) -- (1.0,0);
  \draw[thick] (0,0) -- (0.65,0);
  \draw[thick] (0.65,-0.18) -- (0.65,0.18);
  \draw[very thick] (1.0,-0.32) -- (1.0,0.32);
  \node[below] at (0.82,-0.35) {6 V};
  \node[above] at (0,1.7) {$+6$ V};
  \node[above] at (2.3,1.7) {$P$};
  \node[above] at (4.3,1.7) {$Q$};
  \node[right] at (6.6,0.8) {$B$};
  \draw[thick] (6.6,0) -- (6.6,-0.35);
  \draw[thick] (6.25,-0.35) -- (6.95,-0.35);
  \draw[thick] (6.38,-0.5) -- (6.82,-0.5);
  \draw[thick] (6.5,-0.65) -- (6.7,-0.65);
\end{tikzpicture}
\end{center}

\textbf{Solution.} Earthing sets $V_B=0$, but does not by itself change the currents. The three equal resistors share 6 V equally, so each drop is 2 V. The positive terminal is at $+6$ V; the next points are $+4$ V and $+2$ V, then B is 0 V.
\end{exercise}

\begin{exercise}
\textbf{Question.} A 6 V battery and a 12 V battery are connected in the same series loop with a $2\,\Omega$ and a $4\,\Omega$ resistor, arranged so the two batteries drive current the same way round. Find the loop current, then the p.d. across the point pair $PQ$ that spans the $2\,\Omega$ resistor and the 6 V battery together.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm,>=stealth]
  \draw[thick] (0,0) -- (0,2.2) -- (0.7,2.2);
  \draw[thick] (0.7,1.85) rectangle (2.2,2.55) node[pos=.5] {$2\,\Omega$};
  \draw[thick] (2.2,2.2) -- (3.0,2.2);
  \draw[thick] (3.0,1.85) rectangle (4.5,2.55) node[pos=.5] {$4\,\Omega$};
  \draw[thick] (4.5,2.2) -- (5.5,2.2) -- (5.5,0) -- (4.75,0);
  \draw[thick] (0,0) -- (0.85,0);
  \draw[very thick] (0.85,-0.32) -- (0.85,0.32);
  \draw[thick] (1.2,-0.18) -- (1.2,0.18);
  \draw[thick] (1.2,0) -- (3.0,0);
  \draw[very thick] (3.0,-0.32) -- (3.0,0.32);
  \draw[thick] (3.35,-0.18) -- (3.35,0.18);
  \draw[thick] (3.35,0) -- (5.5,0);
  \node[below] at (1.03,-0.38) {6 V};
  \node[below] at (3.18,-0.38) {12 V};
  \fill (0,0) circle (2pt) node[below left] {$P$};
  \fill (2.2,2.2) circle (2pt) node[above] {$Q$};
  \draw[->,blue!70!black,thick] (1.0,2.85) -- (4.5,2.85) node[midway,above] {$I$};
\end{tikzpicture}
\end{center}

\textbf{Solution.} When sources aid each other their emfs add; when they oppose, subtract. Here they aid, so the net emf is $6+12=18$ V around a total resistance $2+4=6\,\Omega$:
\[
I=\frac{\text{net emf}}{\text{total }R}=\frac{18}{6}=3.0\text{ A}.
\]
Across $PQ$, the $2\,\Omega$ resistor drops $IR=3.0\times2=6$ V while the 6 V battery raises the potential by 6 V in the opposite sense, so
\[
V_{PQ}=6-6=\boxed{0\text{ V}}.
\]
Always fix a direction round the loop first, then add emfs that push that way and subtract those that push back.
\end{exercise}

\begin{mdframed}[backgroundcolor=green!5,leftline=true,linecolor=green!60!black,linewidth=2pt]
\textbf{Cells and capacity}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item Identical cells \textbf{in series} add emf ($n$ cells give $n\mathcal E$). \textbf{In parallel} the emf is unchanged (still $\mathcal E$), but they last longer.
  \item Battery capacity in ampere-hours is a charge: $1\text{ A h}=1\text{ A}\times3600\text{ s}=3600$ C. Energy available is $W=VQ=V(It)$. Example: a 11.1 V, 4.8 A h pack stores $11.1\times4.8\times3600\approx1.9\times10^{5}$ J.
\end{itemize}
\end{mdframed}

\section{Terminal Potential Difference}

An ideal source has no internal resistance, so terminal p.d. equals emf. A real source has internal resistance $r$:
\[
\boxed{V_{\rm terminal}=\mathcal E-Ir}.
\]

\needspace{10\baselineskip}
\begin{exercise}
\textbf{Question.} A cell of emf 3.0 V and internal resistance $0.50\,\Omega$ supplies 1.0 A. Find its terminal p.d.

\textbf{Solution.}
\[
V_{\rm terminal}=3.0-(1.0)(0.50)=\boxed{2.5\text{ V}}.
\]
The missing 0.5 V is the p.d. across the internal resistance. With no current, $Ir=0$ and the terminal p.d. returns to the emf.
\end{exercise}

\section{Resistance and Ohm's Law}

For any component at a particular operating point,
\[
\boxed{R=\frac{V}{I}}.
\]
An \textbf{ohmic} component at constant temperature has constant $R$, so $V\propto I$. Not every conductor is ohmic: a filament heats up, causing its resistance to change.

\begin{exercise}
\textbf{Question.} A 1.5 V p.d. is applied across a $2.0\,\Omega$ lamp. Find the current, treating its resistance as 2.0 $\Omega$ at this operating point.
\[
I=\frac{V}{R}=\frac{1.5}{2.0}=\boxed{0.75\text{ A}}.
\]
\end{exercise}

\begin{exercise}
\textbf{Question.} A resistance wire gives the straight line below through the origin. Find its resistance, and state how the line changes for a shorter wire of the same material and radius.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm,>=stealth]
  \draw[->] (0,0) -- (4,0) node[right] {$I$/A};
  \draw[->] (0,0) -- (0,3.4) node[above] {$V$/V};
  \draw[very thick,blue!70!black] (0,0) -- (3.2,3.2);
  \draw[dashed] (2,0) node[below] {\footnotesize $2.0$} -- (2,2) -- (0,2) node[left] {\footnotesize $4.0$};
  \draw[very thick,red!70!black,dotted] (0,0) -- (3.4,1.7);
  \node[red!70!black] at (3.2,1.15) {\footnotesize shorter};
\end{tikzpicture}
\end{center}

\textbf{Solution.} The line is straight through the origin, so the slope is the resistance. Reading a convenient point, $V=4.0$ V at $I=2.0$ A:
\[
R=\frac{V}{I}=\frac{4.0}{2.0}=\boxed{2.0\ \Omega}.
\]
A shorter wire has smaller $R=\rho\ell/A$, so the slope is smaller (the dotted line). Because $V=IR$, the graph still passes through the origin.
\end{exercise}

\begin{exercise}
\textbf{Question.} A metal wire is connected to a fixed $5.0$ V supply. Its resistance is $5\,\Omega$ at $25^\circ$C and rises to $12\,\Omega$ at $200^\circ$C. The ammeter reads $1.0$ A at $25^\circ$C. Find the reading at $200^\circ$C.

\textbf{Solution.} The supply voltage across the wire stays $V=IR=(1.0)(5)=5.0$ V. At the higher temperature the resistance is larger, so
\[
I=\frac{V}{R}=\frac{5.0}{12}=\boxed{0.42\text{ A}}.
\]
Hotter metal means more resistance and, at fixed voltage, less current. This is why a filament lamp is \emph{not} ohmic.
\end{exercise}

\begin{mdframed}[backgroundcolor=yellow!10,leftline=true,linecolor=yellow!60!black,linewidth=2pt]
\textbf{Reading graphs correctly}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item On a $V$-against-$I$ graph, the slope is $R$ only for a straight line through the origin.
  \item For a non-ohmic component, the operating resistance at a point is the ratio $V/I$, not automatically the tangent slope.
  \item A filament lamp's resistance increases as it becomes hotter.
\end{itemize}
\end{mdframed}

\section{Resistivity and Wire Dimensions}

For a uniform wire,
\[
\boxed{R=\rho\frac{\ell}{A}}, \qquad A=\pi r^2=\frac{\pi d^2}{4}.
\]
Resistivity $\rho$ is a material property at a stated temperature. The correct unit is $\Omega\,\mathrm m$.

\begin{exercise}
\textbf{Question.} A wire of length $\ell$ and diameter $d$ has resistance $10\,\Omega$. A second wire of the same material has length $2\ell$ and diameter $0.5d$. Find its resistance.

The area factor is $(0.5)^2=0.25$. Hence
\[
\frac{R'}{R}=\frac{\ell'}{\ell}\frac{A}{A'}=2\left(\frac{1}{0.25}\right)=8,
\qquad R'=\boxed{80\,\Omega}.
\]
Halving diameter does not merely double resistance; it quarters area and therefore multiplies resistance by four.
\end{exercise}

\begin{exercise}
\textbf{Question.} Two rods of the same material are joined end-to-end. The first has length $2\ell$, diameter $2d$, and resistance $r$. The second has length $\ell$ and diameter $d$. Find the total resistance.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick,fill=blue!8] (0,0.35) rectangle (4,1.25);
  \draw[thick,fill=green!8] (4,0.55) rectangle (6,1.05);
  \draw[<->] (0,1.55) -- (4,1.55) node[midway,above] {$2\ell$};
  \draw[<->] (4,1.55) -- (6,1.55) node[midway,above] {$\ell$};
  \draw[<->] (-0.35,0.35) -- (-0.35,1.25) node[midway,left] {$2d$};
  \draw[<->] (6.35,0.55) -- (6.35,1.05) node[midway,right] {$d$};
  \node at (2,0.8) {$R_1=r$};
  \node at (5,0.8) {$R_2=?$};
\end{tikzpicture}
\end{center}

For the first rod, $r\propto 2\ell/(2d)^2=\ell/(2d^2)$. For the second, $R_2\propto\ell/d^2$, so $R_2=2r$. They are end-to-end, hence in series:
\[
R_{\rm total}=r+2r=\boxed{3r}.
\]
\end{exercise}


