\begin{mdframed}[backgroundcolor=red!5,leftline=true,linecolor=red,linewidth=2pt]
\textbf{Topology traps}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item Components that look side-by-side are not necessarily parallel. Compare their two end nodes.
  \item In parallel, the smaller resistance carries the larger current.
  \item $R_{\rm parallel}$ is always smaller than the smallest branch resistance.
\end{itemize}
\end{mdframed}

\section{Ammeter and Voltmeter}

\begin{exercise}
\textbf{Question.} How should current through a resistor and p.d. across it be measured?

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick] (0,0) -- (0,2.2) -- (1.1,2.2);
  \draw[thick] (1.55,2.2) circle (0.45); \node at (1.55,2.2) {A};
  \draw[thick] (2,2.2) -- (2.7,2.2);
