\begin{exercise}
\textbf{Question.} Closing a switch places an ideal wire directly across AB. What is the voltage across AB after closing?

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick] (0,1.2) -- (1.2,1.2);
  \fill (1.2,1.2) circle (2pt) node[above left] {A};
  \draw[thick] (1.2,0.85) rectangle (3.2,1.55) node[pos=.5] {$R$};
  \fill (3.2,1.2) circle (2pt) node[above right] {B};
  \draw[thick] (3.2,1.2) -- (4.4,1.2);
  \draw[thick] (1.2,1.2) -- (1.2,0.2) -- (1.75,0.2);
  \fill (1.75,0.2) circle (2pt);
  \fill (2.65,0.2) circle (2pt);
  \draw[thick] (1.75,0.2) -- (2.58,0.55);
  \draw[->,blue!70!black,thick] (2.0,-0.2) -- (2.45,-0.2) node[midway,below] {close};
  \draw[thick] (2.65,0.2) -- (3.2,0.2) -- (3.2,1.2);
\end{tikzpicture}
\end{center}

Both A and B lie on the same ideal conductor, so they are equipotential:
\[
\boxed{V_{AB}=0}.
\]
Any resistor bypassed by that wire also has zero p.d. and zero current. If the short is across a source, current is limited only by internal and wire resistance and can become dangerously large.
\end{exercise}

\section{Power and Brightness}

Electrical power is the rate of energy transfer:
\[
\boxed{P=VI=I^2R=\frac{V^2}{R}}, \qquad \boxed{W=Pt}.
\]
Choose the form that matches what is held constant.

\begin{exercise}
\textbf{Question.} A resistor $3R$ connected to emf $V$ dissipates power $P$. Find the power when resistance $R$ is connected to emf $2V$.
\[
P=\frac{V^2}{3R}, \qquad P'=\frac{(2V)^2}{R}=\frac{4V^2}{R}=\boxed{12P}.
\]
\end{exercise}

\begin{exercise}
\textbf{Question.} A bulb is connected to an ideal battery. Which makes it dimmest: a low or high resistance in series, or either resistance in parallel?

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \node[font=\small] at (2.0,2.6) {series resistor};
  \draw[thick] (0,0) -- (0,1.8) -- (0.6,1.8);
  \draw[thick] (0.6,1.5) rectangle (1.8,2.1) node[pos=.5] {$R_s$};
  \draw[thick] (1.8,1.8) -- (2.5,1.8);
