A series resistor raises total resistance and reduces current. For the bulb, $P_b=I^2R_b$, so a high series resistance gives the smallest $I$ and the dimmest bulb. An added parallel branch does not change the bulb's p.d. when the battery is ideal, so its power is unchanged.
\end{exercise}

\begin{exercise}
\textbf{Question.} One bulb X is in series with a parallel pair Y and Z. All bulbs are identical. Z burns out. Predict X and Y.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick] (0,0) -- (0,2.0) -- (0.7,2.0);
  \draw[thick] (1.15,2.0) circle (0.45); \node at (1.15,2.0) {X};
  \draw[thick] (1.6,2.0) -- (2.4,2.0) -- (2.4,2.8) -- (3.1,2.8);
  \draw[thick] (3.55,2.8) circle (0.45); \node at (3.55,2.8) {Y};
  \draw[thick] (4.0,2.8) -- (4.7,2.8) -- (4.7,2.0);
  \draw[thick] (2.4,2.0) -- (2.4,1.2) -- (3.1,1.2);
  \draw[thick] (3.55,1.2) circle (0.45); \node at (3.55,1.2) {Z};
  \draw[thick] (4.0,1.2) -- (4.7,1.2) -- (4.7,2.0) -- (5.3,2.0) -- (5.3,0) -- (0.9,0);
  \draw[red!70!black,very thick] (3.2,0.85) -- (3.9,1.55);
  \draw[red!70!black,very thick] (3.9,0.85) -- (3.2,1.55);
  \draw[thick] (0,0) -- (0.55,0);
