% ============================================================
% content.tex - Simple Circuits Study Notes
% Example-driven notes based primarily on Success Key MC Q5-Q30,
% with Book 4 and 4_ch02_MC_e.pdf used for definitions and checks.
% ============================================================

\section{Electric Circuit and Water System}

A battery is like a pump: it provides a ``push'' to make charge flow. Both are closed loops i.e. the moving stuff circulates without being used up.

\begin{center}
{\small
\noindent\begin{tabularx}{\linewidth}{p{34mm} p{34mm} X}
\toprule
\textbf{Electric circuit} & \textbf{Water system} & \textbf{Shared idea} \\
\midrule
Charge & Water volume & The moving quantity is conserved i.e. it circulates without being used up. \\
Current $I$ (A) & Flow rate $Q$ (L s$^{-1}$) & How much passes a point per second. \\
Potential & Pressure level & A value at one location (not a difference). \\
Potential difference $V$ (V) & Pressure difference $\Delta P$ & The ``push'' that drives the flow between two points. \\
Battery & Pump & Adds energy to the moving quantity per unit of itself. \\
Lamp / resistor & Turbine / narrow pipe & Converts the flow's energy into another form. \\
\bottomrule
\end{tabularx}}
\end{center}

\section{Current and Charge}

\textbf{What is current?} Current ($I$) is the \emph{rate of flow of electric charge} i.e. how much charge passes a point in a wire per second. The unit is the ampere (A), where $1\text{ A}=1\text{ C s}^{-1}$.

\textbf{What does ``energy changes form'' mean?} When charge flows through a device such as a lamp, it transfers energy. The charge arrives with \emph{high electrical energy} and leaves with \emph{less} i.e. the missing energy has been converted into light and heat. The charge itself is \textbf{not used up}; it keeps circulating. Total energy is conserved, just transformed into a different form.

\myskip
\textbf{Series circuit.} The diagram below shows a complete series circuit. Charge flows out of the positive ($+$) terminal of the battery, through the lamp, and back into the negative ($-$) terminal.

\begin{center}
  \begin{tikzpicture}[x=1cm, y=1cm, >=stealth, line width=1pt]
    % ---- Circuit loop ----
    \draw (0,0.5) -- (0,3.2) -- (5,3.2) -- (5,0.5) -- (0,0.5);

    % ---- Battery on the left ----
    \draw[line width=1pt] (-0.45,3.2) -- (0.45,3.2);   % + plate (long)
    \draw[line width=2.6pt] (-0.22,0.5) -- (0.22,0.5);  % - plate (short thick)
    \node[left, font=\footnotesize] at (-0.5,3.2) {$+$};
    \node[left, font=\footnotesize] at (-0.5,0.5) {$-$};
    \node[left, align=center, font=\footnotesize] at (-0.85,1.85) {battery};

    % ---- Lamp on the right ----
    \draw[fill=white] (5,1.85) circle (0.45);
    \draw (4.66,1.85) arc (180:360:0.34);
    \node[right, font=\footnotesize] at (5.55,1.85) {lamp};

    % ---- Current arrows (clockwise) ----
    \draw[->, blue!70!black, line width=1.3pt] (0.5,3.6) -- (4.5,3.6) node[midway, above, blue!70!black, font=\footnotesize] {$I$ (same everywhere)};

    % ---- Energy labels ----
    \node[anchor=south, font=\footnotesize\bfseries, red!70!black] at (5.0,3.6) {$E$ high};
    \node[anchor=north, font=\footnotesize, red!70!black] at (5.0,0.0) {$E$ low (light + heat)};

    % ---- Light arrow ----
    \draw[->, red!70!black, very thin] (5.5,2.45) .. controls +(0.4, 0.5) .. +(0.9, 0.4)
      node[red!70!black, right, font=\footnotesize] {light};
    % ---- Heat arrow ----
    \draw[->, red!70!black, very thin] (5.2,1.25) .. controls +(0.4, -0.45) .. +(0.9, -0.35)
      node[red!70!black, right, font=\footnotesize] {heat};
  \end{tikzpicture}
\end{center}

\begin{itemize}
  \item \textbf{Charge is conserved.} The same amount of charge that enters the lamp leaves it.
  \item \textbf{Current is the same everywhere} in a series circuit, i.e. the rate of charge flow does not slow down inside a component.
  \item \textbf{Energy changes form.} Electrical energy is transformed into light and thermal energy inside the lamp.
\end{itemize}

\myskip
\textbf{Direction of current.} Conventional current is defined as the direction that \emph{positive charge} would flow, i.e. from the positive ($+$) terminal of a battery, through the circuit, to the negative ($-$) terminal. In most circuits the actual moving charges are \emph{electrons}, which carry negative charge and therefore move in the \emph{opposite direction}.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm,>=stealth,line width=0.9pt]
  % ---- Circuit loop ----
  \draw (0,1.7) -- (0,3) -- (5,3) -- (5,0) -- (0,0) -- (0,1.3);

  % ---- Battery ----
  \draw[line width=1pt]   (-0.4,1.7) -- (0.4,1.7);
  \draw[line width=2.6pt] (-0.22,1.3) -- (0.22,1.3);
  \node[left] at (-0.42,1.72) {$+$};
  \node[left] at (-0.42,1.28) {$-$};
  \node[left,align=center,font=\footnotesize] at (-0.75,1.5) {battery};

  % ---- Lamp ----
  \draw[fill=white] (5,1.5) circle (0.45);
  \draw (5-0.34,1.5) arc (180:360:0.34);
  \node[right,font=\footnotesize] at (5.6,1.5) {lamp};

  % ---- Conventional current: blue, out of + terminal, clockwise ----
  \draw[->,blue!70!black,line width=1.4pt] (0.6,3.42) -- (4.4,3.42);
  \node[blue!70!black,above,font=\footnotesize] at (2.5,3.5) {conventional current $I$ (+ to $-$)};

  % ---- Electron flow: red, opposite direction ----
  \draw[->,red!70!black,line width=1.4pt] (4.4,2.58) -- (0.6,2.58);
  \node[red!70!black,below,font=\footnotesize] at (2.5,2.5) {electron flow ($-$ to $+$)};
\end{tikzpicture}
\end{center}

\myskip
\begin{mdframed}[backgroundcolor=red!5,leftline=true,linecolor=red,linewidth=2pt]
\textbf{Common traps}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item Use the magnitude of electron charge $e=1.60\times10^{-19}$ C when finding current magnitude.
  \item Convert minutes to seconds and mA to A before using $Q=It$.
  \item Charges do not move more slowly after a resistor in a steady series circuit. The current is the same at every point.
\end{itemize}
\end{mdframed}

\myskip
\begin{exercise}
\textbf{Question.} A lamp carries a steady current of $0.30$ A for 2 minutes. Find the charge passing through it. Does the lamp use up charge?

\textbf{Solution.} Current is the rate of flow of charge:
\[
\boxed{I=\frac{Q}{t}} \qquad \Longrightarrow \qquad Q=It.
\]
Convert time first: $2$ min $=120$ s. Therefore
\[
Q=(0.30)(120)=\boxed{36\text{ C}}.
\]
The lamp does \emph{not} use up charge. In steady operation, 36 C enters the lamp and 36 C leaves it. The lamp transfers electrical energy to light and thermal energy.
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} $1.88\times10^{18}$ electrons flow through a resistor each second. Find the current. (Electron charge magnitude $e=1.60\times10^{-19}$ C.)

\textbf{Solution.} Total charge per second is the number of electrons times the charge on each:
\[
\boxed{I=\frac{ne}{t}} \qquad I=\frac{(1.88\times10^{18})(1.60\times10^{-19})}{1}=\boxed{0.301\text{ A}}.
\]
Here $n$ is a pure count of electrons, so $Q=ne$ before dividing by time. Watch the powers of ten: $10^{18}\times10^{-19}=10^{-1}$.
\end{exercise}

\section{Potential Difference and EMF}

Potential is energy per unit positive charge at one point. Potential difference (p.d.) is the energy transferred per unit charge between two points:
\[
\boxed{V=\frac{W}{Q}} \qquad 1\text{ V}=1\text{ J C}^{-1}.
\]

EMF ($\mathcal E$) is the energy supplied by a source per unit charge:
\[
\boxed{\mathcal E=\frac{W_{\rm supplied}}{Q}}.
\]

\myskip
\begin{exercise}
\textbf{Question.} A cell supplies 12 J when 6 C passes through it. Find its emf. If a 1.0 V resistor carries 0.50 C, how much energy is converted in the resistor?

\textbf{Solution.}
\[
\mathcal E=\frac{W_{\rm supplied}}{Q}=\frac{12}{6}=\boxed{2.0\text{ V}},
\qquad
W_{\rm converted}=VQ=(1.0)(0.50)=\boxed{0.50\text{ J}}.
\]
A source gives energy to charge; a resistor converts electrical energy to other forms.
\end{exercise}

\myskip
\textbf{The potential ladder.} As charge moves around a complete loop, its potential rises at the source and falls at each component. For an ideal cell,
\[
\boxed{\text{total emf}=\text{sum of potential drops}}.
\]
A component causes no potential change if it is bypassed by an ideal wire.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[->] (0,0) -- (8.5,0) node[right] {position around circuit};
  \draw[->] (0,0) -- (0,4.4) node[above] {potential};
  \draw[very thick] (0.7,0.7) -- (1.7,0.7);
  \draw[very thick,->] (1.7,0.7) -- (1.7,3.7) node[midway,right] {cell: rise $\mathcal E$};
  \draw[very thick] (1.7,3.7) -- (4.5,3.7);
  \draw[very thick,->] (4.5,3.7) -- (4.5,2.2) node[midway,right] {$V_1$};
  \draw[very thick] (4.5,2.2) -- (6.5,2.2);
  \draw[very thick,->] (6.5,2.2) -- (6.5,0.7) node[midway,right] {$V_2$};
  \draw[very thick] (6.5,0.7) -- (8,0.7);
\end{tikzpicture}
\end{center}

\myskip
\begin{exercise}
\textbf{Question.} A 6 V supply is connected across three identical $2\,\Omega$ resistors in series. Point B, at the negative terminal, is earthed. Find the potentials after the first and second resistors when moving from the positive terminal.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick] (0,0) -- (0,1.7) -- (0.6,1.7);
  \draw[thick] (0.6,1.4) rectangle (2.0,2.0) node[pos=.5] {$2\,\Omega$};
  \draw[thick] (2.0,1.7) -- (2.6,1.7);
  \draw[thick] (2.6,1.4) rectangle (4.0,2.0) node[pos=.5] {$2\,\Omega$};
  \draw[thick] (4.0,1.7) -- (4.6,1.7);
  \draw[thick] (4.6,1.4) rectangle (6.0,2.0) node[pos=.5] {$2\,\Omega$};
  \draw[thick] (6.0,1.7) -- (6.6,1.7) -- (6.6,0) -- (1.0,0);
  \draw[thick] (0,0) -- (0.65,0);
  \draw[thick] (0.65,-0.18) -- (0.65,0.18);
  \draw[very thick] (1.0,-0.32) -- (1.0,0.32);
  \node[below] at (0.82,-0.35) {6 V};
  \node[above] at (0,1.7) {$+6$ V};
  \node[above] at (2.3,1.7) {$P$};
  \node[above] at (4.3,1.7) {$Q$};
  \node[right] at (6.6,0.8) {$B$};
  \draw[thick] (6.6,0) -- (6.6,-0.35);
  \draw[thick] (6.25,-0.35) -- (6.95,-0.35);
  \draw[thick] (6.38,-0.5) -- (6.82,-0.5);
  \draw[thick] (6.5,-0.65) -- (6.7,-0.65);
\end{tikzpicture}
\end{center}

\textbf{Solution.} Earthing sets $V_B=0$, but does not by itself change the currents. The three equal resistors share 6 V equally, so each drop is 2 V. The positive terminal is at $+6$ V; the next points are $+4$ V and $+2$ V, then B is 0 V.
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} A 6 V battery and a 12 V battery are connected in the same series loop with a $2\,\Omega$ and a $4\,\Omega$ resistor, arranged so the two batteries drive current the same way round. Find the loop current, then the p.d. across the point pair $PQ$ that spans the $2\,\Omega$ resistor and the 6 V battery together.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm,>=stealth]
  \draw[thick] (0,0) -- (0,2.2) -- (0.7,2.2);
  \draw[thick] (0.7,1.85) rectangle (2.2,2.55) node[pos=.5] {$2\,\Omega$};
  \draw[thick] (2.2,2.2) -- (3.0,2.2);
  \draw[thick] (3.0,1.85) rectangle (4.5,2.55) node[pos=.5] {$4\,\Omega$};
  \draw[thick] (4.5,2.2) -- (5.5,2.2) -- (5.5,0) -- (4.75,0);
  \draw[thick] (0,0) -- (0.85,0);
  \draw[very thick] (0.85,-0.32) -- (0.85,0.32);
  \draw[thick] (1.2,-0.18) -- (1.2,0.18);
  \draw[thick] (1.2,0) -- (3.0,0);
  \draw[very thick] (3.0,-0.32) -- (3.0,0.32);
  \draw[thick] (3.35,-0.18) -- (3.35,0.18);
  \draw[thick] (3.35,0) -- (5.5,0);
  \node[below] at (1.03,-0.38) {6 V};
  \node[below] at (3.18,-0.38) {12 V};
  \fill (0,0) circle (2pt) node[below left] {$P$};
  \fill (2.2,2.2) circle (2pt) node[above] {$Q$};
  \draw[->,blue!70!black,thick] (1.0,2.85) -- (4.5,2.85) node[midway,above] {$I$};
\end{tikzpicture}
\end{center}

\textbf{Solution.} When sources aid each other their emfs add; when they oppose, subtract. Here they aid, so the net emf is $6+12=18$ V around a total resistance $2+4=6\,\Omega$:
\[
I=\frac{\text{net emf}}{\text{total }R}=\frac{18}{6}=3.0\text{ A}.
\]
Across $PQ$, the $2\,\Omega$ resistor drops $IR=3.0\times2=6$ V while the 6 V battery raises the potential by 6 V in the opposite sense, so
\[
V_{PQ}=6-6=\boxed{0\text{ V}}.
\]
Always fix a direction round the loop first, then add emfs that push that way and subtract those that push back.
\end{exercise}

\myskip
\begin{mdframed}[backgroundcolor=green!5,leftline=true,linecolor=green!60!black,linewidth=2pt]
\textbf{Cells and capacity}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item Identical cells \textbf{in series} add emf ($n$ cells give $n\mathcal E$). \textbf{In parallel} the emf is unchanged (still $\mathcal E$), but they last longer.
  \item Battery capacity in ampere-hours is a charge: $1\text{ A h}=1\text{ A}\times3600\text{ s}=3600$ C. Energy available is $W=VQ=V(It)$. Example: an 11.1 V, 4.8 A h pack stores $11.1\times4.8\times3600\approx1.9\times10^{5}$ J.
\end{itemize}
\end{mdframed}

\section{Terminal Potential Difference}

An ideal source has no internal resistance, so terminal p.d. equals emf. A real source has internal resistance $r$:
\[
\boxed{V_{\rm terminal}=\mathcal E-Ir}.
\]

\myskip
\begin{exercise}
\textbf{Question.} A cell of emf 3.0 V and internal resistance $0.50\,\Omega$ supplies 1.0 A. Find its terminal p.d.

\textbf{Solution.}
\[
V_{\rm terminal}=3.0-(1.0)(0.50)=\boxed{2.5\text{ V}}.
\]
The missing 0.5 V is the p.d. across the internal resistance. With no current, $Ir=0$ and the terminal p.d. returns to the emf.
\end{exercise}

\section{Resistance and Ohm's Law}

For any component at a particular operating point,
\[
\boxed{R=\frac{V}{I}}.
\]
An \textbf{ohmic} component at constant temperature has constant $R$, so $V\propto I$. Not every conductor is ohmic: a filament heats up, causing its resistance to change.

\myskip
\begin{exercise}
\textbf{Question.} A 1.5 V p.d. is applied across a $2.0\,\Omega$ lamp. Find the current, treating its resistance as 2.0 $\Omega$ at this operating point.
\[
I=\frac{V}{R}=\frac{1.5}{2.0}=\boxed{0.75\text{ A}}.
\]
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} A resistance wire gives a straight line through the origin on a $V$-$I$ graph. Find its resistance, and state how the line changes for a shorter wire of the same material and radius.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm,>=stealth]
  \draw[->] (0,0) -- (4,0) node[right] {$I$/A};
  \draw[->] (0,0) -- (0,3.4) node[above] {$V$/V};
  \draw[very thick,blue!70!black] (0,0) -- (3.2,3.2);
  \draw[dashed] (2,0) node[below] {\footnotesize $2.0$} -- (2,2) -- (0,2) node[left] {\footnotesize $4.0$};
  \draw[very thick,red!70!black,dotted] (0,0) -- (3.4,1.7);
  \node[red!70!black] at (3.2,1.15) {\footnotesize shorter};
\end{tikzpicture}
\end{center}

\textbf{Solution.} The line is straight through the origin, so the slope is the resistance. Reading a convenient point, $V=4.0$ V at $I=2.0$ A:
\[
R=\frac{V}{I}=\frac{4.0}{2.0}=\boxed{2.0\ \Omega}.
\]
A shorter wire has smaller $R=\rho\ell/A$, so the slope is smaller (the dotted line). Because $V=IR$, the graph still passes through the origin.
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} A metal wire is connected to a fixed $5.0$ V supply. Its resistance is $5\,\Omega$ at $25^\circ$C and rises to $12\,\Omega$ at $200^\circ$C. The ammeter reads $1.0$ A at $25^\circ$C. Find the reading at $200^\circ$C.

\textbf{Solution.} The supply voltage across the wire stays $V=IR=(1.0)(5)=5.0$ V. At the higher temperature the resistance is larger, so
\[
I=\frac{V}{R}=\frac{5.0}{12}=\boxed{0.42\text{ A}}.
\]
Hotter metal means more resistance and, at fixed voltage, less current. This is why a filament lamp is \emph{not} ohmic.
\end{exercise}

\myskip
\begin{mdframed}[backgroundcolor=yellow!10,leftline=true,linecolor=yellow!60!black,linewidth=2pt]
\textbf{Reading graphs correctly}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item On a $V$-against-$I$ graph, the slope is $R$ only for a straight line through the origin.
  \item For a non-ohmic component, the operating resistance at a point is the ratio $V/I$, not automatically the tangent slope.
  \item A filament lamp's resistance increases as it becomes hotter.
\end{itemize}
\end{mdframed}

\section{Series and Parallel Circuits}

In a \textbf{parallel circuit}, components are connected side-by-side on separate branches. Charge splits between the branches, i.e. each branch receives part of the total charge. The total charge is still conserved.

\begin{center}
  \begin{tikzpicture}[x=1cm, y=1cm, >=stealth, line width=1pt]
    % ---- Top wire: left to right ----
    \draw[thick] (-2, 2) -- (0, 2);
    % ---- Bottom wire: left to right ----
    \draw[thick] (-2, 0) -- (0, 0);
    % ---- Right vertical return ----
    \draw[thick, ->] (4.5, 0) -- (4.5, 2) -- (3.5, 2) node[midway, above] {$I_{\text{total}}$};

    % ---- Junction dots ----
    \fill (0, 2) circle (0.1);
    \fill (4.5, 2) circle (0.1);
    \fill (0, 0) circle (0.1);
    \fill (4.5, 0) circle (0.1);

    % ---- Top branch: wire + lamp 1 ----
    \draw[thick] (0, 2) -- (1.8, 2) node[midway, above, font=\footnotesize] {$I_1$};
    \node[draw, thick, fill=blue!10, minimum width=1.5cm, minimum height=0.9cm,
          align=center, font=\footnotesize] at (2.7, 2) {lamp 1};
    \draw[thick] (3.6, 2) -- (4.5, 2);

    % ---- Bottom branch: wire + lamp 2 ----
    \draw[thick] (0, 0) -- (1.8, 0) node[midway, below, font=\footnotesize] {$I_2$};
    \node[draw, thick, fill=blue!10, minimum width=1.5cm, minimum height=0.9cm,
          align=center, font=\footnotesize] at (2.7, 0) {lamp 2};
    \draw[thick] (3.6, 0) -- (4.5, 0);

    % ---- Battery on the left vertical wire ----
    \draw[thick] (-2.0, 0.8) rectangle (-1.3, 1.2);
    \node[left, font=\footnotesize] at (-2.1, 1.0) {battery};
    \node[left, font=\tiny] at (-2.1, 1.2) {$+$};
    \node[left, font=\tiny] at (-2.1, 0.8) {$-$};

    % ---- Incoming current arrow ----
    \draw[thick, ->] (-2.8, 2) -- (-2.1, 2) node[midway, above, font=\footnotesize] {$I_{\text{total}}$};

    % ---- Annotations: current values ----
    \node[anchor=south, font=\footnotesize\bfseries, blue!70!black] at (2.7, 2.9) {$I_1 = I_{\text{total}}/2$};
    \node[anchor=north, font=\footnotesize\bfseries, blue!70!black] at (2.7, -0.3) {$I_2 = I_{\text{total}}/2$};

    % ---- Junction connection (bottom) ----
    \draw[thick] (0, 2) -- (0, 0);
    \draw[thick] (4.5, 2) -- (4.5, 0);
  \end{tikzpicture}
\end{center}

\begin{itemize}
  \item Each branch receives part of the total current: $I_1 + I_2 = I_{\text{total}}$.
  \item If both lamps are identical (equal resistance), the current splits equally: $I_1 = I_2 = I_{\text{total}}/2$.
  \item The current through each lamp is \emph{less} than the total current.
  \item In the water analogy: one pipe splits into two smaller pipes; the total water flow rate is conserved, but each branch carries a fraction.
\end{itemize}

\myskip
\begin{mdframed}[backgroundcolor=blue!5,leftline=true,linecolor=blue,linewidth=2pt]
\textbf{Series and parallel at a glance}

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \node[font=\bfseries] at (1.8,2.8) {Series};
  \draw[thick] (0,1.8) -- (0.7,1.8);
  \draw[thick] (0.7,1.45) rectangle (2.1,2.15) node[pos=.5] {$R_1$};
  \draw[thick] (2.1,1.8) -- (2.8,1.8);
  \draw[thick] (2.8,1.45) rectangle (4.2,2.15) node[pos=.5] {$R_2$};
  \draw[thick] (4.2,1.8) -- (4.9,1.8);
  \draw[->,blue,thick] (0.2,2.35) -- (4.7,2.35) node[midway,above] {same $I$};

  \node[font=\bfseries] at (7.6,2.8) {Parallel};
  \draw[thick] (5.3,1.8) -- (6,1.8) -- (6,2.4);
  \draw[thick] (6,2.4) -- (6.5,2.4);
  \draw[thick] (6.5,2.05) rectangle (8.1,2.75) node[pos=.5] {$R_1$};
  \draw[thick] (8.1,2.4) -- (8.6,2.4) -- (8.6,1.8) -- (9.3,1.8);
  \draw[thick] (6,1.8) -- (6,1.2) -- (6.5,1.2);
  \draw[thick] (6.5,0.85) rectangle (8.1,1.55) node[pos=.5] {$R_2$};
  \draw[thick] (8.1,1.2) -- (8.6,1.2) -- (8.6,1.8);
  \node[blue] at (7.3,0.35) {same $V$ across both branches};
\end{tikzpicture}
\end{center}

{\small
\noindent\begin{tabularx}{\linewidth}{p{28mm} X X}
\toprule
 & \textbf{Series} & \textbf{Parallel} \\
\midrule
Identifying test & One unbranched path; shared junction has no other connection & Both ends of each component join the same two nodes \\
Current & Same through every component & Splits and recombines: $I=I_1+I_2+\cdots$ \\
Voltage & $V=V_1+V_2+\cdots$ & Same across every branch \\
Resistance & $R_{\rm eq}=R_1+R_2+\cdots$ & $1/R_{\rm eq}=1/R_1+1/R_2+\cdots$ \\
\bottomrule
\end{tabularx}}
\end{mdframed}

\myskip
\begin{exercise}
\textbf{Question.} A 3.0 V battery supplies a $4\,\Omega$ resistor in series with a parallel pair of $1\,\Omega$ and $2\,\Omega$. Find the current through the $1\,\Omega$ resistor.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick,blue] (0,0) -- (0,2.4) -- (1,2.4);
  \draw[thick] (1,2.05) rectangle (2.5,2.75) node[pos=.5] {$4\,\Omega$};
  \draw[thick,red] (2.5,2.4) -- (3.2,2.4) -- (3.2,3.1) -- (3.8,3.1);
  \draw[thick] (3.8,2.75) rectangle (5.3,3.45) node[pos=.5] {$1\,\Omega$};
  \draw[thick,green!60!black] (5.3,3.1) -- (5.9,3.1) -- (5.9,2.4);
  \draw[thick,red] (3.2,2.4) -- (3.2,1.7) -- (3.8,1.7);
  \draw[thick] (3.8,1.35) rectangle (5.3,2.05) node[pos=.5] {$2\,\Omega$};
  \draw[thick,green!60!black] (5.3,1.7) -- (5.9,1.7) -- (5.9,2.4) -- (6.6,2.4) -- (6.6,0) -- (1.1,0);
  \draw[thick,blue] (0,0) -- (0.75,0);
  \draw[thick] (0.75,0.15) -- (0.75,-0.15);
  \draw[very thick] (1.1,0.3) -- (1.1,-0.3);
  \node[below] at (0.93,-0.35) {3.0 V};
  \node[blue,above] at (0.45,1.15) {node A};
  \node[red,above] at (3.2,3.25) {node B};
  \node[green!60!black,above] at (6.25,1.15) {node C};
\end{tikzpicture}
\end{center}

Blue, red, and green wires mark three different potentials. Both parallel resistors connect from red node B to green node C, so they must have the same p.d.

First reduce the parallel pair:
\[
R_p=\frac{(1)(2)}{1+2}=\frac{2}{3}\,\Omega,
\qquad R_{\rm total}=4+\frac{2}{3}=\frac{14}{3}\,\Omega.
\]
Thus $I_{\rm total}=3/(14/3)=9/14$ A. The p.d. across the parallel pair is
\[
V_p=I_{\rm total}R_p=\frac{9}{14}\cdot\frac{2}{3}=\frac{3}{7}\text{ V}.
\]
Therefore
\[
I_{1\Omega}=\frac{V_p}{1}=\boxed{0.429\text{ A}}.
\]
Check: current in the $2\,\Omega$ branch is $0.214$ A; the branch currents add to $0.643$ A.
\end{exercise}

\myskip
\begin{mdframed}[backgroundcolor=red!5,leftline=true,linecolor=red,linewidth=2pt]
\textbf{Topology traps}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item Components that look side-by-side are not necessarily parallel. Compare their two end nodes.
  \item In parallel, the smaller resistance carries the larger current.
  \item $R_{\rm parallel}$ is always smaller than the smallest branch resistance.
\end{itemize}
\end{mdframed}

\section{Resistivity and Wire Dimensions}

For a uniform wire,
\[
\boxed{R=\rho\frac{\ell}{A}}, \qquad A=\pi r^2=\frac{\pi d^2}{4}.
\]
Resistivity $\rho$ is a material property at a stated temperature. The correct unit is $\Omega\,\mathrm m$.

\myskip
\begin{exercise}
\textbf{Question.} A wire of length $\ell$ and diameter $d$ has resistance $10\,\Omega$. A second wire of the same material has length $2\ell$ and diameter $0.5d$. Find its resistance.

The area factor is $(0.5)^2=0.25$. Hence
\[
\frac{R'}{R}=\frac{\ell'}{\ell}\frac{A}{A'}=2\left(\frac{1}{0.25}\right)=8,
\qquad R'=\boxed{80\,\Omega}.
\]
Halving diameter does not merely double resistance; it quarters area and therefore multiplies resistance by four.
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} Two rods of the same material are joined end-to-end. The first has length $2\ell$, diameter $2d$, and resistance $r$. The second has length $\ell$ and diameter $d$. Find the total resistance.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick,fill=blue!8] (0,0.35) rectangle (4,1.25);
  \draw[thick,fill=green!8] (4,0.55) rectangle (6,1.05);
  \draw[<->] (0,1.55) -- (4,1.55) node[midway,above] {$2\ell$};
  \draw[<->] (4,1.55) -- (6,1.55) node[midway,above] {$\ell$};
  \draw[<->] (-0.35,0.35) -- (-0.35,1.25) node[midway,left] {$2d$};
  \draw[<->] (6.35,0.55) -- (6.35,1.05) node[midway,right] {$d$};
  \node at (2,0.8) {$R_1=r$};
  \node at (5,0.8) {$R_2=?$};
\end{tikzpicture}
\end{center}

For the first rod, $r\propto 2\ell/(2d)^2=\ell/(2d^2)$. For the second, $R_2\propto\ell/d^2$, so $R_2=2r$. They are end-to-end, hence in series:
\[
R_{\rm total}=r+2r=\boxed{3r}.
\]
\end{exercise}

\section{Ammeter and Voltmeter}

\begin{exercise}
\textbf{Question.} How should current through a resistor and p.d. across it be measured?

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick] (0,0) -- (0,2.2) -- (1.1,2.2);
  \draw[thick] (1.55,2.2) circle (0.45); \node at (1.55,2.2) {A};
  \draw[thick] (2,2.2) -- (2.7,2.2);
  \draw[thick] (2.7,1.85) rectangle (4.4,2.55) node[pos=.5] {$R$};
  \draw[thick] (4.4,2.2) -- (5.5,2.2) -- (5.5,0) -- (0,0);
  \draw[thick] (2.7,2.2) -- (2.7,3.5) -- (3.1,3.5);
  \draw[thick] (3.55,3.5) circle (0.45); \node at (3.55,3.5) {V};
  \draw[thick] (4,3.5) -- (4.4,3.5) -- (4.4,2.2);
  \draw[thick] (0.8,0.15) -- (0.8,-0.15);
  \draw[very thick] (1.15,0.3) -- (1.15,-0.3);
\end{tikzpicture}
\end{center}

The ammeter is in series so the component current passes through it. An ideal ammeter has $R_A=0$. The voltmeter is in parallel because voltage is measured between two points. An ideal voltmeter has $R_V\to\infty$ and draws no current.
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} A high-resistance voltmeter across points A and B reads 3 V. Replacing it by a low-resistance ammeter connects A and B almost directly by wire. What happens?

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \node at (0.1,1.1) {before:};
  \fill (1.2,1.1) circle (2pt) node[above] {A};
  \draw[thick] (1.2,1.1) -- (2.0,1.1);
  \draw[thick] (2.45,1.1) circle (0.45); \node at (2.45,1.1) {V};
  \draw[thick] (2.9,1.1) -- (3.7,1.1);
  \fill (3.7,1.1) circle (2pt) node[above] {B};
  \node[below] at (2.45,0.55) {3 V};
  \draw[->,thick] (4.15,1.1) -- (5.0,1.1);
  \node at (5.65,1.1) {after:};
  \fill (6.55,1.1) circle (2pt) node[above] {A};
  \draw[thick] (6.55,1.1) -- (7.35,1.1);
  \draw[thick] (7.8,1.1) circle (0.45); \node at (7.8,1.1) {A};
  \draw[thick] (8.25,1.1) -- (9.05,1.1);
  \fill (9.05,1.1) circle (2pt) node[above] {B};
\end{tikzpicture}
\end{center}

The ammeter creates a short path between A and B. Their p.d. becomes approximately zero, and a large current may flow in that path. Never connect an ammeter directly across a cell or component.
\end{exercise}

\myskip
\begin{mdframed}[backgroundcolor=yellow!10,leftline=true,linecolor=yellow!60!black,linewidth=2pt]
A voltmeter in series behaves approximately as an open circuit. An ammeter in parallel behaves approximately as a short circuit. Use these replacements when predicting a circuit before calculating.
\end{mdframed}

\section{Open and Short Circuits}

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \node[font=\bfseries] at (2,2.6) {Open circuit};
  \draw[thick] (0,1.5) -- (1.4,1.5);
  \draw[thick] (1.4,1.5) -- (2.2,2.05);
  \fill (1.4,1.5) circle (2pt); \fill (2.8,1.5) circle (2pt);
  \draw[thick] (2.8,1.5) -- (4,1.5);
  \node at (2,0.8) {$I=0$, but a p.d. may exist across the gap};

  \node[font=\bfseries] at (7,2.6) {Short circuit};
  \draw[thick] (5,1.5) -- (5.8,1.5);
  \draw[thick] (5.8,1.15) rectangle (7.5,1.85) node[pos=.5] {$R$};
  \draw[thick] (7.5,1.5) -- (8.3,1.5);
  \draw[thick] (5.8,1.5) -- (5.8,0.55) -- (7.5,0.55) -- (7.5,1.5);
  \node at (6.7,0) {$V_R=0$; current bypasses $R$};
\end{tikzpicture}
\end{center}

\myskip
\begin{exercise}
\textbf{Question.} Closing a switch places an ideal wire directly across AB. What is the voltage across AB after closing?

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick] (0,1.2) -- (1.2,1.2);
  \fill (1.2,1.2) circle (2pt) node[above left] {A};
  \draw[thick] (1.2,0.85) rectangle (3.2,1.55) node[pos=.5] {$R$};
  \fill (3.2,1.2) circle (2pt) node[above right] {B};
  \draw[thick] (3.2,1.2) -- (4.4,1.2);
  \draw[thick] (1.2,1.2) -- (1.2,0.2) -- (1.75,0.2);
  \fill (1.75,0.2) circle (2pt);
  \fill (2.65,0.2) circle (2pt);
  \draw[thick] (1.75,0.2) -- (2.58,0.55);
  \draw[->,blue!70!black,thick] (2.0,-0.2) -- (2.45,-0.2) node[midway,below] {close};
  \draw[thick] (2.65,0.2) -- (3.2,0.2) -- (3.2,1.2);
\end{tikzpicture}
\end{center}

Both A and B lie on the same ideal conductor, so they are equipotential:
\[
\boxed{V_{AB}=0}.
\]
Any resistor bypassed by that wire also has zero p.d. and zero current. If the short is across a source, current is limited only by internal and wire resistance and can become dangerously large.
\end{exercise}

\section{Power and Brightness}

Electrical power is the rate of energy transfer:
\[
\boxed{P=VI=I^2R=\frac{V^2}{R}}, \qquad \boxed{W=Pt}.
\]
Choose the form that matches what is held constant.

\myskip
\begin{exercise}
\textbf{Question.} A resistor $3R$ connected to emf $V$ dissipates power $P$. Find the power when resistance $R$ is connected to emf $2V$.
\[
P=\frac{V^2}{3R}, \qquad P'=\frac{(2V)^2}{R}=\frac{4V^2}{R}=\boxed{12P}.
\]
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} A bulb is connected to an ideal battery. Which makes it dimmest: a low or high resistance in series, or either resistance in parallel?

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \node[font=\small] at (2.0,2.6) {series resistor};
  \draw[thick] (0,0) -- (0,1.8) -- (0.6,1.8);
  \draw[thick] (0.6,1.5) rectangle (1.8,2.1) node[pos=.5] {$R_s$};
  \draw[thick] (1.8,1.8) -- (2.5,1.8);
  \draw[thick] (2.95,1.8) circle (0.45); \node at (2.95,1.8) {$\times$};
  \draw[thick] (3.4,1.8) -- (4.0,1.8) -- (4.0,0) -- (0.9,0);
  \draw[thick] (0,0) -- (0.55,0);
  \draw[very thick] (0.55,-0.3) -- (0.55,0.3);
  \draw[thick] (0.9,-0.17) -- (0.9,0.17);

  \node[font=\small] at (7.0,2.6) {parallel resistor};
  \draw[thick] (5,0) -- (5,1.8) -- (5.8,1.8);
  \draw[thick] (6.25,1.8) circle (0.45); \node at (6.25,1.8) {$\times$};
  \draw[thick] (6.7,1.8) -- (8.6,1.8) -- (8.6,0) -- (5.9,0);
  \draw[thick] (5.8,1.8) -- (5.8,2.55) -- (6.35,2.55);
  \draw[thick] (6.35,2.25) rectangle (7.65,2.85) node[pos=.5] {$R_p$};
  \draw[thick] (7.65,2.55) -- (8.0,2.55) -- (8.0,1.8);
  \draw[thick] (5,0) -- (5.55,0);
  \draw[very thick] (5.55,-0.3) -- (5.55,0.3);
  \draw[thick] (5.9,-0.17) -- (5.9,0.17);
\end{tikzpicture}
\end{center}

A series resistor raises total resistance and reduces current. For the bulb, $P_b=I^2R_b$, so a high series resistance gives the smallest $I$ and the dimmest bulb. An added parallel branch does not change the bulb's p.d. when the battery is ideal, so its power is unchanged.
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} One bulb X is in series with a parallel pair Y and Z. All bulbs are identical. Z burns out. Predict X and Y.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick] (0,0) -- (0,2.0) -- (0.7,2.0);
  \draw[thick] (1.15,2.0) circle (0.45); \node at (1.15,2.0) {X};
  \draw[thick] (1.6,2.0) -- (2.4,2.0) -- (2.4,2.8) -- (3.1,2.8);
  \draw[thick] (3.55,2.8) circle (0.45); \node at (3.55,2.8) {Y};
  \draw[thick] (4.0,2.8) -- (4.7,2.8) -- (4.7,2.0);
  \draw[thick] (2.4,2.0) -- (2.4,1.2) -- (3.1,1.2);
  \draw[thick] (3.55,1.2) circle (0.45); \node at (3.55,1.2) {Z};
  \draw[thick] (4.0,1.2) -- (4.7,1.2) -- (4.7,2.0) -- (5.3,2.0) -- (5.3,0) -- (0.9,0);
  \draw[red!70!black,very thick] (3.2,0.85) -- (3.9,1.55);
  \draw[red!70!black,very thick] (3.9,0.85) -- (3.2,1.55);
  \draw[thick] (0,0) -- (0.55,0);
  \draw[very thick] (0.55,-0.3) -- (0.55,0.3);
  \draw[thick] (0.9,-0.17) -- (0.9,0.17);
\end{tikzpicture}
\end{center}

Initially the load is $R+R/2=3R/2$. After Z opens, the load is $R+R=2R$, so total current decreases: X becomes dimmer. The parallel section changes from $R/2$ to $R$ and receives a larger fraction of the supply voltage; Y becomes brighter. The battery current decreases.
\end{exercise}

\myskip
\begin{mdframed}[backgroundcolor=blue!5,leftline=true,linecolor=blue,linewidth=2pt]
\textbf{Brightness checklist}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item Identical bulbs: compare power.
  \item Same current (series): use $P=I^2R$.
  \item Same voltage (parallel): use $P=V^2/R$.
  \item After a switch changes, redraw the new circuit and recalculate the current or voltage. Do not rely on ``current chooses the easier path'' alone.
\end{itemize}
\end{mdframed}

\myskip
\section{A Reliable Method for Mixed Problems}

\begin{mdframed}[backgroundcolor=green!5,leftline=true,linecolor=green!60!black,linewidth=2pt]
\begin{enumerate}[label=\textbf{Step \arabic*:},itemsep=5pt,topsep=3pt]
  \item \textbf{Redraw the operating circuit.} Replace closed switches and ideal ammeters by wires; remove open branches and ideal voltmeters.
  \item \textbf{Mark nodes.} Every continuous ideal wire is one potential. Components sharing both end nodes are parallel.
  \item \textbf{Reduce resistance from the inside out.} Keep the original circuit visible.
  \item \textbf{Find total current.} Use $I_{\rm total}=\mathcal E/R_{\rm total}$ for an ideal source, or include internal resistance.
  \item \textbf{Work backwards.} Series: same current. Parallel: same voltage. Use $V=IR$ on one component at a time.
  \item \textbf{Check conservation.} Junction currents balance; rises and drops around a loop balance; source power equals total load power for an ideal circuit.
\end{enumerate}
\end{mdframed}

\myskip
\begin{exercise}
\textbf{Question.} A 3.0 V ideal battery is connected to three identical $2\,\Omega$ resistors. One resistor is in series with two resistors in parallel. Find (a) battery current, (b) current in either parallel branch, and (c) p.d. across the parallel pair.

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm]
  \draw[thick] (0,0) -- (0,2.0) -- (0.7,2.0);
  \draw[thick] (0.7,1.65) rectangle (2.2,2.35) node[pos=.5] {$2\,\Omega$};
  \draw[thick] (2.2,2.0) -- (2.9,2.0) -- (2.9,2.8) -- (3.5,2.8);
  \draw[thick] (3.5,2.45) rectangle (5.0,3.15) node[pos=.5] {$2\,\Omega$};
  \draw[thick] (5.0,2.8) -- (5.6,2.8) -- (5.6,2.0);
  \draw[thick] (2.9,2.0) -- (2.9,1.2) -- (3.5,1.2);
  \draw[thick] (3.5,0.85) rectangle (5.0,1.55) node[pos=.5] {$2\,\Omega$};
  \draw[thick] (5.0,1.2) -- (5.6,1.2) -- (5.6,2.0) -- (6.3,2.0) -- (6.3,0) -- (1.0,0);
  \draw[thick] (0,0) -- (0.65,0);
  \draw[very thick] (0.65,-0.3) -- (0.65,0.3);
  \draw[thick] (1.0,-0.17) -- (1.0,0.17);
  \node[below] at (0.82,-0.35) {3.0 V};
\end{tikzpicture}
\end{center}

\textbf{Solution.}
\[
R_p=\frac{2}{2}=1\,\Omega,
\qquad R_{\rm total}=2+1=3\,\Omega.
\]
Thus
\[
I_{\rm battery}=\frac{3.0}{3}=\boxed{1.0\text{ A}}.
\]
The two identical branches share current equally, so each carries $\boxed{0.50\text{ A}}$. Their common p.d. is
\[
V_p=(0.50)(2)=\boxed{1.0\text{ V}}.
\]
Check: the series resistor drops $(1.0)(2)=2.0$ V, and $2.0+1.0=3.0$ V.
\end{exercise}

\myskip
\section{Quick Reference and Exam Checks}

\begin{center}
{\small
\noindent\begin{tabularx}{\linewidth}{p{34mm} X X}
\toprule
\textbf{Quantity} & \textbf{Definition / formula} & \textbf{Unit and meaning} \\
\midrule
Current & $I=Q/t$ & A; charge flow per second \\
Potential difference & $V=W/Q$ & V; energy transferred per coulomb \\
EMF & $\mathcal E=W_{\rm supplied}/Q$ & V; energy supplied per coulomb \\
Resistance & $R=V/I$ & $\Omega$ \\
Uniform wire & $R=\rho\ell/A$ & $\rho$ in $\Omega\,\mathrm m$ \\
Power & $P=VI=I^2R=V^2/R$ & W; energy transferred per second \\
Energy & $W=Pt=VQ$ & J \\
\bottomrule
\end{tabularx}}
\end{center}

\myskip
\begin{mdframed}[backgroundcolor=yellow!10,leftline=true,linecolor=yellow!60!black,linewidth=2pt]
\textbf{Ten-second answer check}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item Is a parallel equivalent resistance smaller than every branch?
  \item Do branch currents add to the total current?
  \item Do potential drops add to the source emf around a complete loop?
  \item Does an ideal wire have zero p.d. along it?
  \item Is the ammeter in series and the voltmeter in parallel?
  \item Did you use area proportional to diameter squared in $R=\rho\ell/A$?
  \item For power comparisons, did you identify whether current or voltage is common?
\end{itemize}
\end{mdframed}

\myskip
\begin{mdframed}[backgroundcolor=red!5,leftline=true,linecolor=red,linewidth=2pt]
\textbf{Language that earns physics marks}
\begin{itemize}[itemsep=2pt,topsep=3pt]
  \item Say ``the same current flows through series components,'' not ``current is shared''.
  \item Say ``parallel branches have the same p.d.,'' not ``they have the same current''.
  \item Say ``the source supplies energy to charge'' and ``the resistor converts electrical energy''.
  \item A voltmeter reads a difference between two potentials; a single point does not have a p.d.
\end{itemize}
\end{mdframed}

